  private ownPartOf(claim: Claim, due: string): string {
    if (due === 'n/a' || (claim.shares ?? []).length === 0) return due;
    return changeFrom(due, sumDues(claim.shares.map((h) => this.partOf(claim, h, due)).filter((p) => p !== 'n/a')));
